// --- Checkout form: custom searchable Province + City dropdowns ---
// A visible dropdown list (not the browser's native datalist popup, which
// some browsers/environments do not render). The input accepts any typed
// value (manual entry) — the list only suggests matches. Choosing a
// province narrows the city suggestions to that province; clearing it
// restores the full city list.
(function () {
  var CSS = ".dex-combo{position:relative;display:block}" +
    ".dex-combo-list{position:absolute;left:0;right:0;top:calc(100% + 4px);z-index:60;max-height:220px;overflow:auto;background:#fff;border:1.5px solid #e67e22;border-radius:10px;box-shadow:0 10px 28px rgba(0,0,0,.14);padding:4px}" +
    ".dex-combo-list[hidden]{display:none}" +
    ".dex-combo-item{padding:9px 12px;font-size:15px;cursor:pointer;border-radius:7px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}" +
    ".dex-combo-item:hover,.dex-combo-item.active{background:#fdf1e7}" +
    ".dex-combo-empty{padding:9px 12px;font-size:14px;color:#888}";
  function injectCss() {
    if (document.getElementById("dex-combo-css")) return;
    var st = document.createElement("style");
    st.id = "dex-combo-css";
    st.textContent = CSS;
    document.head.appendChild(st);
  }
  function makeCombo(input, getValues) {
    var wrap = input.parentElement;
    if (!wrap || !wrap.classList.contains("dex-combo")) return null;
    var list = wrap.querySelector(".dex-combo-list");
    if (!list) return null;
    var activeIdx = -1;
    function render(show) {
      var q = input.value.trim().toLowerCase();
      var values = getValues();
      var matches = [];
      for (var i = 0; i < values.length; i++) {
        if (!q || values[i].toLowerCase().indexOf(q) !== -1) matches.push(values[i]);
        if (matches.length >= 60) break;
      }
      list.textContent = "";
      activeIdx = -1;
      if (!matches.length) {
        var em = document.createElement("div");
        em.className = "dex-combo-empty";
        em.textContent = "No match — you can still type your own value.";
        list.appendChild(em);
      } else {
        for (var j = 0; j < matches.length; j++) {
          (function (val) {
            var d = document.createElement("div");
            d.className = "dex-combo-item";
            d.textContent = val;
            d.addEventListener("mousedown", function (e) {
              e.preventDefault();
              input.value = val;
              hide();
              input.dispatchEvent(new Event("change", { bubbles: true }));
            });
            list.appendChild(d);
          })(matches[j]);
        }
      }
      list.hidden = !show;
    }
    function hide() { list.hidden = true; }
    input.addEventListener("input", function () { render(true); });
    input.addEventListener("focus", function () { render(true); });
    input.addEventListener("keydown", function (e) {
      var els = list.querySelectorAll(".dex-combo-item");
      if (e.key === "ArrowDown" || e.key === "ArrowUp") {
        e.preventDefault();
        if (!els.length) return;
        if (list.hidden) { render(true); els = list.querySelectorAll(".dex-combo-item"); }
        activeIdx = e.key === "ArrowDown"
          ? (activeIdx + 1) % els.length
          : (activeIdx - 1 + els.length) % els.length;
        for (var k = 0; k < els.length; k++) els[k].classList.toggle("active", k === activeIdx);
        if (els[activeIdx]) els[activeIdx].scrollIntoView({ block: "nearest" });
      } else if (e.key === "Enter" && activeIdx >= 0 && !list.hidden) {
        var els2 = list.querySelectorAll(".dex-combo-item");
        if (els2[activeIdx]) {
          e.preventDefault();
          input.value = els2[activeIdx].textContent;
          hide();
          input.dispatchEvent(new Event("change", { bubbles: true }));
        }
      } else if (e.key === "Escape") {
        hide();
      }
    });
    input.addEventListener("blur", function () { setTimeout(hide, 120); });
    document.addEventListener("click", function (e) { if (!wrap.contains(e.target)) hide(); });
    return { input: input, list: list, render: render, hide: hide };
  }
  function initDexLocationLists() {
    var provInput = document.getElementById("province");
    var cityInput = document.getElementById("city");
    if (!provInput || !cityInput) return;
    if (!window.DEX_PROVINCES || !window.DEX_CITIES_BY_PROVINCE) return;
    injectCss();
    makeCombo(provInput, function () { return window.DEX_PROVINCES; });
    var cityCombo = makeCombo(cityInput, function () {
      var p = provInput.value.trim();
      return window.DEX_CITIES_BY_PROVINCE[p] || window.DEX_CITIES_ALL || [];
    });
    // When the province changes, refresh the city list right away so the
    // user does not have to re-tap the City field to see the new matches.
    function refreshCity() {
      if (cityCombo) cityCombo.render(document.activeElement === cityInput);
    }
    provInput.addEventListener("input", refreshCity);
    provInput.addEventListener("change", refreshCity);
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initDexLocationLists);
  } else {
    initDexLocationLists();
  }
})();
